-- =============================================================================
-- FoT-AMS sample (DEMO) data: departments, users, courses  -  REPEATABLE and NON-DESTRUCTIVE
--
-- Run AFTER schema.sql:
--   mysql -u <admin_user> -p faculty_ams -e "source database/sample_data.sql"
--
-- Changed from earlier versions, which inserted FIXED ids (1-30) with plain INSERTs:
--   * a row is inserted only when it does not exist yet. The natural key is used
--     (department_code / username + e-mail / registration_no / course_code), never an id.
--   * no existing row is updated or deleted, except a blank DOB on the verified tg1002 demo account
--     is filled with a clearly sample-only date; a real user, department or course is never overwritten.
--   * ids are generated by MySQL. On an EMPTY database they come out exactly as before
--     (admin 1, lecturers 2-6, technical officers 7-10, students 11-30, courses 1-8).
--   * lecturers / students / course rows are attached only to the DEMO accounts (e-mail ending
--     @fot.example.lk), so a real account that happens to share a username is left alone. Any demo
--     account that was skipped for that reason is listed in the last result.
--
-- Demo logins (the same password for every user of a role). CHANGE OR REMOVE THESE ACCOUNTS before the
-- system holds real people's data:
--   ADMIN              admin                      / admin123
--   LECTURER           lec.perera ... lec.bandara / lecturer123
--   TECHNICAL_OFFICER  to.kumara ... to.wijesinghe / officer123
--   STUDENT            tg1001 ... tg1016, tg0950, tg0951, tg0960, tg0961 / student123
--
-- Contents (assignment minimum: 1 admin, 5 lecturers, 4 technical officers, 20 undergraduates incl. repeat
-- and batch-missed): 1 admin, 5 lecturers, 4 technical officers, 20 undergraduates
--   16 REGULAR (batch B09), 2 REPEAT and 2 BATCH_MISSED (batch B08 following B09 modules).
-- The course list is a PLACEHOLDER Level 2 Semester 1 list. It is NOT the official B09 timetable:
-- replace it with the modules from your official timetable (Admin module > Courses) before submission.
-- Passwords are PBKDF2 hashes; create new ones with:
--   java -cp target/classes com.facultyams.security.PasswordUtil <password>
-- =============================================================================

USE faculty_ams;

-- ---- departments (natural key: department_code)
INSERT INTO departments (department_code, department_name)
SELECT 'DICT', 'Department of Information and Communication Technology' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM departments WHERE department_code = 'DICT' OR department_name = 'Department of Information and Communication Technology');
INSERT INTO departments (department_code, department_name)
SELECT 'DET', 'Department of Engineering Technology' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM departments WHERE department_code = 'DET' OR department_name = 'Department of Engineering Technology');
